const JS_TOPIC_PATTERN = "^campus/(?<building>B\\d{3})/(?<system>ahu|boiler|pump|room)/(?<equipment>[a-z0-9_]+)/(?<point_class>[a-z0-9_]+)$";

// Validate one BMS message against contracts/validation_rules.json.
// Mirrors src/validate.py; tests assert both implement the same rules.
const rules = global.get('BMS_RULES');
// rules.topic_pattern is written in Python named-group syntax for
// src/validate.py; V8 needs (?<name>...) instead of (?P<name>...).
const topicPattern = new RegExp(JS_TOPIC_PATTERN);

const raw = msg.payload;
const topic = msg.topic;

function reject(reason) {
  return { topic, payload: typeof raw === 'string' ? raw : JSON.stringify(raw), reason };
}

const m = topicPattern.exec(topic);
if (!m) { return reject('TOPIC_PATTERN'); }
const pointClass = m[4];

let body;
try { body = (typeof raw === 'string') ? JSON.parse(raw) : raw; }
catch (e) { return reject('MALFORMED_JSON'); }
if (typeof body !== 'object' || body === null || Array.isArray(body)) { return reject('MISSING_FIELD'); }

for (const f of rules.payload_schema.required_fields) {
  if (!(f in body)) { return reject('MISSING_FIELD'); }
}
if (!rules.payload_schema.allowed_quality.includes(body.quality)) { return reject('QUALITY_INVALID'); }
if (typeof body.value !== 'number' || Number.isNaN(body.value)) { return reject('NON_NUMERIC_VALUE'); }
if (Math.abs(body.value) > rules.max_value_abs) { return reject('OUT_OF_RANGE'); }

const ts = new Date(body.ts);
if (isNaN(ts.getTime())) { return reject('TIMESTAMP_FORMAT'); }
const now = Date.now();
if (ts.getTime() > now + rules.max_future_skew_minutes * 60000) { return reject('TIMESTAMP_IN_FUTURE'); }
if (ts.getTime() < now - rules.max_past_age_hours * 3600000) { return reject('TIMESTAMP_TOO_OLD'); }

const rule = rules.rules_by_point_class[pointClass];
if (!rule) { return reject('MISSING_FIELD'); }
if (String(body.unit) !== String(rule.unit)) { return reject('UNIT_MISMATCH'); }
if (body.value < rule.min || body.value > rule.max) { return reject('OUT_OF_RANGE'); }

// registry lookup: topic -> canonical point_id
const pointId = global.get('BMS_POINTS_BY_TOPIC')[topic];
if (!pointId) { return reject('UNKNOWN_POINT_ID'); }

return { ts: ts.toISOString(), point_id: pointId, value: body.value, unit: body.unit, quality: body.quality };

// Batcher. Node-RED 4 dropped the core `buffer` node, so batching happens
// here: accumulate in flow context and emit when the batch is full (500 rows)
// or older than 5 minutes, whichever comes first.
const MAX = 500;
const MAX_AGE_MS = 5 * 60 * 1000;

const state = flow.get('batch') || { rows: [], startedAt: Date.now() };
state.rows.push(msg.payload);

if (state.rows.length >= MAX || Date.now() - state.startedAt >= MAX_AGE_MS) {
  const rows = state.rows;
  flow.set('batch', { rows: [], startedAt: Date.now() });
  // $1 is the JSON array of accepted readings
  return { params: [JSON.stringify(rows)] };
}
flow.set('batch', state);
return null; // hold until the batch flushes

// One row per distinct point_id in the flushed batch, so bms.points
// carries last_seen and the staleness alert can see who went quiet.
const seen = {};
for (const row of JSON.parse(msg.params[0])) {
  seen[row.point_id] = row.ts;
}
const rows = Object.keys(seen).map((id) => ({ point_id: id, last_seen: seen[id] }));
return { params: [JSON.stringify(rows)] };

// Rejected messages keep their reason code for the point-health dashboard.
const rejected = msg.payload;
return { params: [rejected.topic, rejected.payload, rejected.reason] };
